persuasion_principles:
{
  "Reciprocity": {"Explanation": "The email offers the white paper report 'for free' and asks for a favor (calling at 1-800-537-3786) in return, creating a sense of obligation."},
  "Scarcity": {"Explanation": "The email implies that the report will be available on the internet within 5 minutes, creating a sense of urgency."},
  "Authority": {"Explanation": "The email claims that over 100,000 sales professionals have read the white paper report, implying credibility through recognition."},
  "Commitment/Consistency": {"Explanation": "The email references prior behavior (the recipient has read the white paper report) to push further action."},
  "Liking": {"Explanation": "The email uses a personalization (addressing the recipient by 'hi') and a friendly tone to build trust and rapport."},
  "Social proof": {"Explanation": "The email references the number of sales professionals who have read the white paper report (over 100,000) to demonstrate social proof."}
}

